import { type Affordance } from '../affordances';
import { R, ban, deprogram, find, grant, knows, rightThinking, techTok, thinkLevel, type HubView } from '../hubkit';
import { row, open } from './hubafford';
import { TECHS } from './hubs';
import type { World } from '../types';

/**
 * The third part: things that depend on what is happening today (situations), the rule-breaking wild cards, and the things only
 * some kinds of hub or some traits offer. Same tokens as hubafford.ts. The Academy rows are the ones that carry Right Thinking.
 */

const cash = (w: World): number => w.hero.cash;
const rich = (v: HubView): boolean => !!find(v, 'owner');

/** A technique she has never been taught, picked from all of them (the auction, the Master). */
function unknownTech(w: World, rng: { pick<T>(xs: T[]): T }): string | undefined {
  const left = Object.keys(TECHS).filter((t) => !knows(w.hero, t));
  return left.length ? rng.pick(left) : undefined;
}

